@startuml

class Employee {
  + identifyingNumber : string
  + name : string
  + address : string
}

class Client {
  + identifyingNumber : string
  + name : string
  + address : string
  + phone : string
}

class Car {
  + licensePlate : string
  + make : string
  + model : string
  + color : string
}

class CarModel {
}

class PartAccessory {
  + category : string
  + serialNumber : string
  + price : float
}

class AssemblyService {
  + kmsAtTime : int
  + workHours : float
  + admissionDate : date
  + finishDate : date
}

class ServiceItem {
  + quantity : int
}

Client "1" -- "*" Car : owns
Car "*" -- "1" CarModel : isModel
Car "1" -- "*" AssemblyService : undergoes
Employee "1" -- "*" AssemblyService : responsibleFor
AssemblyService "1" -- "1..*" ServiceItem
ServiceItem "*" -- "1" PartAccessory
PartAccessory "*" -- "*" CarModel : fits

@enduml

